#nullable enable // autogenerated

using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Entities;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.axolotlSuitPilot)]
    public class AxolotlSuitPilot : AIEntityBehaviour
    {
        public AxolotlSuitPilot(string nsp, string name) : base(nsp, name)
        {
        }

        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            if (entity.IsDead)
                return;
            switch (entity.State)
            {
                case STATE_WALK:
                case STATE_MELEE_ATTACK:
                    UpdateNormalState(entity);
                    break;

                case STATE_CAST:
                    UpdateCastState(entity);
                    break;
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetModelProperty("NoRemote", !HasRemote(entity));
        }
        public override void PostDeath(Entity entity, DeathInfo info)
        {
            base.PostDeath(entity, info);
            if (entity.IsCasting())
            {
                EndSummoningSuit(entity);
            }
        }
        private void StartSummoningSuit(Entity entity)
        {
            entity.SetCasting(true);
            entity.PlaySound(VanillaSoundID.summonAxolotlSuit);
            var stateTimer = GetStateTimer(entity);
            stateTimer?.ResetSeconds(GetRecallDurationSeconds(entity));

            SummonSuit(entity);
        }
        private void EndSummoningSuit(Entity entity)
        {
            entity.SetCasting(false);
            var stateTimer = GetStateTimer(entity);
            stateTimer?.ResetSeconds(GetRecallSeconds(entity));
        }
        private void UpdateNormalState(Entity entity)
        {
            var suit = DetectNearbySuit(entity);
            if (suit.ExistsAndAlive())
            {
                EnterSuit(entity, suit);
                return;
            }

            if (HasRemote(entity))
            {
                var stateTimer = GetStateTimer(entity);
                if (stateTimer == null)
                {
                    stateTimer = TimerHelper.NewSecondTimer(GetRecallSeconds(entity));
                    SetStateTimer(entity, stateTimer);
                }
                if (stateTimer.RunToExpired(entity.GetAttackSpeed()))
                {
                    StartSummoningSuit(entity);
                }
            }
        }
        private void UpdateCastState(Entity entity)
        {
            var stateTimer = GetStateTimer(entity);
            if (stateTimer == null)
            {
                stateTimer = TimerHelper.NewSecondTimer(GetRecallDurationSeconds(entity));
                SetStateTimer(entity, stateTimer);
            }
            if (stateTimer.RunToExpired())
            {
                EndSummoningSuit(entity);
            }
        }
        public static Entity? SummonSuit(Entity entity)
        {
            var position = entity.Position + entity.GetFacingDirection() * 10 + Vector3.up * 800f;
            var spawnParam = entity.GetSpawnParams();
            spawnParam.SetProperty(AxolotlSuit.PROP_EMPTY, true);
            return entity.Spawn(VanillaEnemyID.axolotlSuit, position, spawnParam);
        }
        public static Entity? DetectNearbySuit(Entity entity)
        {
            return suitDetector.Detect(entity)?.Entity;
        }
        public static void EnterSuit(Entity entity, Entity suit)
        {
            AxolotlSuit.SetEmpty(suit, false);
            AxolotlSuit.SetPilotHPPercent(suit, entity.Health / entity.GetMaxHealth());
            entity.PlaySound(VanillaSoundID.axolotlSuitEnter);
            entity.PlaySound(VanillaSoundID.axolotlSuitAppear);
            entity.Remove();
        }
        public static void SetStateTimer(Entity entity, FrameTimer timer) => entity.SetBehaviourField(PROP_STATE_TIMER, timer);
        public static FrameTimer? GetStateTimer(Entity entity) => entity.GetBehaviourField<FrameTimer>(PROP_STATE_TIMER);
        public static void SetRecallSeconds(Entity entity, float value) => entity.SetBehaviourField(PROP_RECALL_SECONDS, value);
        public static bool HasRemote(Entity entity) => entity.GetBehaviourField<bool>(PROP_HAS_REMOTE);
        public static void SetHasRemote(Entity entity, bool value) => entity.SetBehaviourField(PROP_HAS_REMOTE, value);
        public static float GetRecallSeconds(Entity entity) => entity.GetBehaviourField<float>(PROP_RECALL_SECONDS);
        public static void SetRecallDurationSeconds(Entity entity, float value) => entity.SetBehaviourField(PROP_RECALL_DURATION_SECONDS, value);
        public static float GetRecallDurationSeconds(Entity entity) => entity.GetBehaviourField<float>(PROP_RECALL_DURATION_SECONDS);

        public const int STATE_WALK = LogicEnemyStates.WALK;
        public const int STATE_MELEE_ATTACK = LogicEnemyStates.MELEE_ATTACK;
        public const int STATE_CAST = LogicEnemyStates.CAST;
        public static readonly VanillaEntityPropertyMeta<bool> PROP_HAS_REMOTE = new VanillaEntityPropertyMeta<bool>("has_remote", true);
        public static readonly VanillaEntityPropertyMeta<float> PROP_RECALL_DURATION_SECONDS = new VanillaEntityPropertyMeta<float>("recall_duration_seconds", 1f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_RECALL_SECONDS = new VanillaEntityPropertyMeta<float>("recall_seconds", 10f);
        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_STATE_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("state_timer");
        private static Detector suitDetector = new AxolotlSuitPilotDetector(false)
        {
            factionTarget = FactionTarget.Friendly,
            mask = EntityCollisionHelper.MASK_ENEMY,
        };
    }
}
